cat > /tmp/analyze.mjs <<'EOF'
import fs from 'fs';
const calls=[];
for (const f of fs.readdirSync('/tmp/threads').sort()) { const thread=f.replace('.jsonl','');
 const byId={}; let order=0; const toolCount={};
 for (const line of fs.readFileSync('/tmp/threads/'+f,'utf8').split('\n')) { if(!line.trim()) continue; const b=JSON.parse(line);
  for (const w of b.writes) { if (w.type!=='entry') continue; for (const m of (w.value.model||[])) {
   if (m.role==='assistant') for (const c of m.content||[]) if (c.type==='toolCall') { toolCount[c.name]=(toolCount[c.name]||0)+1; if(c.name==='typescript'){ const code=c.arguments.code||''; const head=code.slice(0, code.indexOf('=>')>0?code.indexOf('=>'):300); const fns=[]; const re=/(\w+)\s*:\s*\{([^{}]*)\}/g; let mm; while((mm=re.exec(head))) for (const n of mm[2].split(',')) { const nm=n.trim().split(/[:\s=]/)[0]; if(nm) fns.push(mm[1]+'.'+nm);} const re2=/^\s*\(?\{\s*([\w\s,]+)\}/; const label=(code.match(/@pit: (\{.*\})/)||[])[1]; const rec={thread,i:order++,id:c.id,fns,label: label?JSON.parse(label).label:(c.arguments.label||''),fid:c.arguments.functionId,saveOnly:c.arguments.saveOnly,named:/^\s*(\/\/.*\n)*\s*async function (\w+)/.exec(code)?.[2],codeLen:code.length,code}; byId[c.id]=rec; calls.push(rec);} }
   if (m.role==='toolResult' && byId[m.toolCallId]) { const r=byId[m.toolCallId]; const t=(m.content||[]).map(x=>x.text||'').join(''); r.isError=m.isError; r.kind=m.details?.failure?.kind; r.path=m.details?.failure?.functionPath; r.resLen=t.length; r.res=t; r.ms=m.durationMs; }
  } } }
 console.log('THREAD',thread,JSON.stringify(toolCount));
}
fs.writeFileSync('/tmp/calls.json', JSON.stringify(calls));
const stats={};
for (const c of calls) for (const fn of new Set(c.fns)) { const s=stats[fn]??={n:0,err:0}; s.n++; if(c.isError) s.err++; }
console.log(JSON.stringify(Object.entries(stats).sort((a,b)=>b[1].n-a[1].n)));
console.log('ERRORS');
for (const c of calls.filter(c=>c.isError)) console.log(`[${c.thread}#${c.i}] ${c.label} | fns=${c.fns.join(',')} | kind=${c.kind} path=${JSON.stringify(c.path)} | ${c.res.replace(/\s+/g,' ').slice(0,350)}`);
EOF
node /tmp/analyze.mjs
